class Solution {
    public int numberOfGoodSubarraySplits(int[] nums){
        final long MOD=1000000007;
        long answer=1;
        int previous=-1;
        for(int i=0;i<nums.length;i++)if(nums[i]==1){
            if(previous!=-1)answer=answer*(i-previous)%MOD;
            previous=i;
        }
        return previous==-1?0:(int)answer;
    }
}

code.kotlin:
class Solution {
    fun numberOfGoodSubarraySplits(nums:IntArray):Int{
        val mod=1000000007L;
        var answer=1L;
        var previous=-1;
        for(i in nums.indices)if(nums[i]==1){
            if(previous!=-1)answer=answer*(i-previous)%mod;
            previous=i
        };
        return if(previous==-1)0 else answer.toInt()
    }
}

